import{_ as p,l,o as d,b as O,d as t,f as S,m as o,q as r}from"./chunks/framework.Tf23FRXt.js";const x=JSON.parse('{"title":"异界深渊月面地下溪谷","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[{"level":3,"title":"BOSS 1 暗黑精灵","slug":"boss-1-暗黑精灵","link":"#boss-1-暗黑精灵","children":[]}]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 达姆希安蚁狮","slug":"boss-2-达姆希安蚁狮","link":"#boss-2-达姆希安蚁狮","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 杜兰特","slug":"boss-3-杜兰特","link":"#boss-3-杜兰特","children":[]}]}],"relativePath":"duty/823.htm.md","filePath":"duty/823.md","lastUpdated":1791101830000}'),b={name:"duty/823.htm.md"};function B(a,s,m,u,k,A){const e=l("Status"),n=l("Role"),i=l("Action");return d(),O("div",null,[s[6]||(s[6]=t("h1",{id:"异界深渊月面地下溪谷",tabindex:"-1"},"异界深渊月面地下溪谷",-1)),s[7]||(s[7]=t("h2",{id:"进场-boss-1",tabindex:"-1"},"进场～BOSS 1",-1)),s[8]||(s[8]=t("p",null,"没什么特别的，可以拉一波。",-1)),s[9]||(s[9]=t("h3",{id:"boss-1-暗黑精灵",tabindex:"-1"},"BOSS 1 暗黑精灵",-1)),s[10]||(s[10]=t("p",null,"场地划分为 4x4 的格子，场地伤害以格子为标记。",-1)),s[11]||(s[11]=t("p",null,"格子上出现紫色的手杖之后，会以手杖格子为中心发射纵横十字方向 AOE，初期为 2 根，后期有 3 根。",-1)),t("p",null,[s[0]||(s[0]=S("第二次开始手杖会消失，需要记住安全区的位置。BOSS 读条",-1)),s[1]||(s[1]=t("mark",null,"十字魔爆",-1)),s[2]||(s[2]=S("时，手杖发出 AOE，被击中的玩家会被附加",-1)),o(e,{id:1738,name:"死亡宣告",dispel:""}),s[3]||(s[3]=S("，",-1)),o(n,{name:"healer"}),s[4]||(s[4]=S("治疗可使用",-1)),o(i,{name:"康复"}),s[5]||(s[5]=S("驱散。",-1))]),s[12]||(s[12]=r('<p>场地上出现蓝色方块和紫色三角的花纹时，BOSS 身上也会出现蓝色方块或紫色三角的图案，与 BOSS 相同图案的地板会发生 AOE，找图案不同的地板躲避。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>可以拉一波，道中体型较大的怪的大范围 AOE 都可以通过眩晕打断（注意白魔神圣造成的眩晕抗性）。</p><h3 id="boss-2-达姆希安蚁狮" tabindex="-1">BOSS 2 达姆希安蚁狮</h3><p>BOSS 读条<mark>滑坡</mark>时，场地出现箭头，读条结束后，所有人沿箭头方向强行移动大约半个场地的距离。</p><p>BOSS 移动到场边读条<mark>蚁狮行军</mark>，同时场地上开始出现红色轨迹预警，轨迹上会经过 2 个石柱。BOSS 沿轨迹造成 AOE 后，跳到场边读条<mark>滑坡</mark>，玩家被强制移动之后，之前被撞到的 2 根石柱会立刻倒下。可以在轨迹预警时观察场边石柱（石柱上有红色叹号），也可以在读条滑坡时观察两侧石柱是否有缺口躲避。</p><p>分摊后地面会出现流沙泉，需要尽快离开流沙范围。</p><h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>道中小怪都可以眩晕打断。</p><h3 id="boss-3-杜兰特" tabindex="-1">BOSS 3 杜兰特</h3><p>读条<mark>双连魔弹</mark>时，场地会连续出现两次螺旋形 AOE 预警，BOSS 会在读条结束后依次连续释放螺旋形 AOE，注意躲避。</p><p>场地上出现紫色魔力球时，需要远离，其造成的 AOE 伤害半径大于 BOSS 目标圈。</p><p>后续的魔力球时，BOSS 会使用技能将球劈开，球上出现箭头，球会沿着箭头方向分成两个，移动一定距离造成圆形 AOE 伤害。</p><p>第三次开始会出现 5 个魔力球，劈开并移动后，只有场地约 1/9 的区域安全。找到 3 个分裂方向完全相同的球，安全区在这 3 个球之一，若其中一个远离其他球，则该球安全，如果没有，则中间球安全。</p><p>BOSS 点名直线分摊并冲锋至场边后，会对场内释放 150° 范围 AOE，注意靠近 BOSS。</p><p>BOSS 身边竖起巨大的尖爪时，会产生尖爪连线方向的非常宽的 AOE，注意在两侧躲避。</p><p>BOSS 旁边出现一个大球并与地面连线时，大球会造成场地范围直径的范围 AOE 伤害，需要尽可能远离着地点靠场边躲避。</p>',17))])}const f=p(b,[["render",B]]);export{x as __pageData,f as default};
